#include "stdlib/math/base/special/log2f.h"
#include "stdlib/number/float32/base/to_word.h"
#include "stdlib/number/float32/base/from_word.h"
#include "stdlib/math/base/assert/is_nanf.h"
#include "stdlib/constants/float32/abs_mask.h"
#include "stdlib/constants/float32/significand_mask.h"
#include "stdlib/constants/float32/exponent_bias.h"
#include "stdlib/constants/float32/ninf.h"
#include "stdlib/math/base/special/kernel_log1pf.h"
#include <stdint.h>

static const float TWO25 = 3.3554432000e+07;  // 0x4c000000
static const float IVLN2HI = 1.4428710938e+00;  // 0x3fb8b000
static const float IVLN2LO = -1.7605285393e-04;  // 0x3de705fc
static const int32_t HIGH_MAX_NORMAL_EXP = 0x7f800000;
static const int32_t HIGH_MIN_NORMAL_EXP = 0x00800000;
static const int32_t HIGH_BIASED_EXP_0 = 0x3f800000;

/**
* Evaluates the binary logarithm (base two) for single-precision floating point values.
*
* @param x    input value
* @return     output value
*
* @example
* float out = stdlib_base_log2f( 4.0f );
* // returns 2.0f
*/ 
float stdlib_base_log2f( const float x ) {
	uint32_t hx;
	int32_t ihx;
	float hfsq;
	uint32_t hi;
	int32_t i;
	int32_t k;
	float lo;
	float xc;
	float f;
	float R;
	float y;
	float hii;

	if ( stdlib_base_is_nanf( x ) || x < 0.0 ) {
		return 0.0 / 0.0; // NaN
	}
	if ( x == 0.0 ){
		return STDLIB_CONSTANT_FLOAT32_NINF;
	}
	xc = x;
	stdlib_base_float32_to_word( x, &hx );
	ihx = (int32_t)hx;
	k = 0;
	if ( ihx < HIGH_MIN_NORMAL_EXP ) {
		// Case: x < 2**-126
		if ( ( ihx & STDLIB_CONSTANT_FLOAT32_HIGH_WORD_ABS_MASK ) == 0 ) {
			return STDLIB_CONSTANT_FLOAT32_NINF;
		}
		k -= 25;

		// Subnormal number, scale up x:
		xc *= TWO25;
		stdlib_base_float32_to_word( xc, &hx );
		ihx = (int32_t)hx;
	}
	if ( ihx >= HIGH_MAX_NORMAL_EXP ) {
		return xc + xc;
	}
	// Case: log(1) = +0
	if ( ihx == HIGH_BIASED_EXP_0 ) {
		return 0;
	}
	k += ( ( ihx>>23 ) - STDLIB_CONSTANT_FLOAT32_EXPONENT_BIAS );
	ihx &= STDLIB_CONSTANT_FLOAT32_HIGH_WORD_SIGNIFICAND_MASK;
	i = ( ihx+0x4afb0d ) & HIGH_MIN_NORMAL_EXP;

	// Normalize x or x/2...
	stdlib_base_float32_from_word( (uint32_t)( ihx|( i^HIGH_BIASED_EXP_0 ) ), &xc );
	k += (i>>23);
	y = (float)k;
	f = xc - (float)1.0;
	hfsq = (float)0.5 * f * f;
	R = stdlib_base_kernel_log1pf( f );

	/*
	* Notes:
	*
	* -   `f-hfsq` must (for args near `1`) be evaluated in extra precision to avoid a large cancellation when `x` is near `sqrt(2)` or `1/sqrt(2)`.This is fairly efficient since `f-hfsq` only depends on `f`, so can be evaluated in parallel with `R`. Not combining `hfsq` with `R` also keeps `R` small (though not as small as a true `lo` term would be), so that extra precision is not needed for terms involving `R`.
	* -   Compiler bugs involving extra precision used to break Dekker's theorem for spitting `f-hfsq` as `hi+lo`. These problems are now automatically avoided as a side effect of the optimization of combining the Dekker splitting step with the clear-low-bits step.
	* -   `y` must (for args near `sqrt(2)` and `1/sqrt(2)`) be added in extra precision to avoid a very large cancellation when `x` is very near these values.  Unlike the above cancellations, this problem is specific to base `2`.  It is strange that adding `+-1` is so much harder than adding `+-ln2` or `+-log10_2`.
	* -   This implementation uses Dekker's theorem to normalize `y+val_hi`, so compiler bugs may reappear in some configurations.
	* -   The multi-precision calculations for the multiplications are routine.
	*/
	if (sizeof(float_t) > sizeof(float))
		return (R - hfsq + f) * ((float_t)IVLN2LO + IVLN2HI) + y;

	hi = f - hfsq;
	stdlib_base_float32_to_word( ihx, &hi );
	hii= (float)hi;
	stdlib_base_float32_from_word( (uint32_t)( ihx & 0xfffff000 ) , &hii );
	lo = ( f - hii ) - hfsq + R;
	return ( ( lo + hi ) * IVLN2LO ) + ( lo * IVLN2HI ) + ( hi * IVLN2HI ) + y;
}
